<?php
function mostrar_pedido($o, $statuses) { ?>
<article data-admin-pedido="<?= (int)$o['id'] ?>" class="panel" id="pedido-<?= (int)$o['id'] ?>"><h2>#<?= (int)$o['id'] ?> · <?= money($o['total']) ?></h2><p><?= h($o['nome_usuario']) ?> · <?= h($o['email']) ?> · <?= h($o['criado_em']) ?> · <?= h($o['tipo_entrega']) ?></p><?php if ($o['tipo_entrega'] === 'delivery'): ?><p><strong>Recebedor:</strong> <?= h($o['recebedor'] ?? '') ?> · <strong>Telefone:</strong> <?= h($o['telefone'] ?? '') ?></p><p><strong>Endereço:</strong> <?= h(!empty($o['rua']) ? $o['rua'] . ', ' . $o['numero'] . ($o['complemento'] ? ', ' . $o['complemento'] : '') . ' — ' . $o['bairro'] . ', ' . $o['cidade'] . '/' . $o['estado'] : $o['endereco']) ?> · CEP <?= h($o['cep'] ?? '') ?></p><p><strong>Referência:</strong> <?= h($o['referencia'] ?? '') ?></p><?php endif; ?><p><strong>Observações:</strong> <?= h($o['observacoes']) ?></p><p>Pagamento <?= h(str_replace('_',' ', $o['forma_pagamento'])) ?></p><form method="post" action="admin_pedidos.php"><input type="hidden" name="csrf" value="<?= h(csrf()) ?>"><input type="hidden" name="pedido_id" value="<?= (int)$o['id'] ?>"><label>Status <select name="status" <?= $o['status']==='cancelado'?'disabled':'' ?>><?php foreach ($statuses as $status): ?><option value="<?= h($status) ?>" <?= $o['status']===$status?'selected':'' ?>><?= h(str_replace('_',' ', $status)) ?></option><?php endforeach; ?></select></label><?php if ($o['status'] !== 'cancelado'): ?><button>Salvar status</button><?php endif; ?></form></article>
<?php }
function mostrar_mensagem($m) { ?>
<article data-admin-mensagem="<?= (int)$m['id'] ?>" class="<?= $m['lida'] ? '' : 'nao-lida' ?>"><h2><?= h($m['assunto']) ?></h2><p><?= h($m['nome']) ?> · <?= h($m['email']) ?> · <?= h($m['data_envio']) ?></p><p class="estado-leitura"><?= $m['lida'] ? 'Lida' : 'Não lida' ?></p><p><?= nl2br(h($m['mensagem'])) ?></p>
<form method="post" action="admin_mensagens.php"><input type="hidden" name="csrf" value="<?= h(csrf()) ?>"><input type="hidden" name="id" value="<?= (int)$m['id'] ?>"><button name="acao" value="<?= $m['lida'] ? 'nao_lida' : 'lida' ?>"><?= $m['lida'] ? 'Marcar como não lida' : 'Marcar como lida' ?></button><button name="acao" value="excluir" onclick="return confirm('Excluir esta mensagem?')">Excluir</button></form></article>
<?php }
